    letter_combinations = {}
    for i in range(len(password)):
        for j in range(i+1, len(password)+1):
            combination = ''.join(sorted(password[i:j]))
            if combination not in letter_combinations:
                letter_combinations[combination] = []
            letter_combinations[combination].append(password[i])

